use gpui::prelude::*;
use kui::components::glass_card::{GlassCard, GlassCardOpenChanged};

let card = cx.new(|cx| {
    GlassCard::new("images/jasmine.jpg", "Portrait of Jasmine Brooks", "Jasmine Brooks", cx)
        .with_id("featured-profile")
        .with_subtitle(Box::new(|_, _| gpui::div().child("Design lead, Lisbon").into_any_element()))
        .with_aside(Box::new(|_, _| gpui::div().child("★ 4.9").into_any_element()))
        .with_body(Box::new(|_, _| {
            gpui::div().child("Design systems and motion.").into_any_element()
        }))
        .with_open(false)
});
window
    .subscribe(&card, cx, |card, event: &GlassCardOpenChanged, w, cx| {
        card.update(cx, |card, cx| card.set_open(event.0, w, cx));
    })
    .detach();

use gpui::prelude::*;
use kui::components::glass_tabbar::{
    GlassTabBar, GlassTabBarCompactChanged, GlassTabBarItem, GlassTabBarValueChanged, GlassTabIcon,
};

let scroll = gpui::ScrollHandle::new();
let bar = cx.new(|cx| {
    GlassTabBar::new(
        vec![
            GlassTabBarItem::new("home", "Home", GlassTabIcon::Home),
            GlassTabBarItem::new("explore", "Explore", GlassTabIcon::Explore),
            GlassTabBarItem::new("saved", "Saved", GlassTabIcon::Saved).with_badge(3),
            GlassTabBarItem::new("profile", "Profile", GlassTabIcon::Profile),
        ],
        cx,
    )
    .with_label("Main")
    .with_action(GlassTabBarItem::new("search", "Search", GlassTabIcon::Search), cx)
    .with_scroll_handle(scroll.clone())
    .with_value("home")
    .with_compact(false)
});
cx.subscribe(&bar, |bar, event: &GlassTabBarValueChanged, cx| {
    bar.update(cx, |bar, cx| bar.set_value(event.0.clone(), cx));
}).detach();
cx.subscribe(&bar, |bar, event: &GlassTabBarCompactChanged, cx| {
    bar.update(cx, |bar, cx| bar.set_compact(event.0, cx));
}).detach();

use gpui::prelude::*;
use kui::components::action_morph::{
    ActionMorph, ActionMorphAction, ActionMorphComposer, ActionMorphSubmit,
};
use kui::primitives::glyph::Glyph;

let create = cx.new(|cx| {
    ActionMorph::new(
        vec![ActionMorphAction::new(
            "task",
            "Task",
            Glyph::Check,
            ActionMorphComposer::new("New task", "What needs doing?", "Add task", "Task added"),
        ).with_shortcut('t')],
        window,
        cx,
    )
    .with_deferred_submit()
    .with_style(|e| e.absolute().bottom(gpui::px(16.)).right(gpui::px(16.)))
});
window.subscribe(&create, cx, |control, submission: &ActionMorphSubmit, w, cx| {
    // This example accepts immediately. Resolve with the persistence result in an app.
    control.update(cx, |control, cx| {
        control.complete(submission.ticket, Ok(()), w, cx);
    });
}).detach();

use gpui::prelude::*;
use kui::components::wallet_stack::{
    WalletStack, WalletStackCard, WalletStackSelected, WalletTransaction, WalletVariant,
};

let wallet = cx.new(|cx| {
    WalletStack::new(
        vec![
            WalletStackCard::new(
                "debit", "Fieldnote", "Everyday debit", "4821", "Jordan Hayes",
                3248.60, "Available",
            )
            .with_expiration("09/29")
            .with_transactions(vec![WalletTransaction::new(
                "split", "Ryan Mitchell", "Dinner split · Today", 36.50,
            )]),
            WalletStackCard::new(
                "credit", "Meridian", "Reserve credit", "0917", "Jordan Hayes",
                1286.44, "Spent in September",
            )
            .with_variant(WalletVariant::Black),
        ],
        cx,
    )
    .with_label("Jordan’s cards")
});
cx.subscribe(&wallet, |_, event: &WalletStackSelected, _| {
    let selected_id = event.0.as_ref().map(|card| card.id.as_ref());
    println!("Opened card: {selected_id:?}");
}).detach();

use gpui::prelude::*;
use kui::components::control_center::{ControlCenter, ControlCenterChanged, FocusMode, NotificationChannel};
use kui::primitives::glyph::Glyph;

let settings = cx.new(|cx| {
    ControlCenter::new(
        vec![
            FocusMode::new("deep", "Deep work", Glyph::Lock, "Only mentions get through", 50),
            FocusMode::new("meeting", "Meetings", Glyph::Clock, "Keep calendar alerts", 30),
        ],
        vec![
            NotificationChannel::new("mentions", "Mentions").with_default_on(true),
            NotificationChannel::new("deploys", "Deploy alerts"),
        ],
        cx,
    )
});
cx.subscribe(&settings, |_, event: &ControlCenterChanged, _| {
    // Persist the settings and apply notification, presenting and text preferences in the host.
    let settings = &event.0;
    println!("Alert volume: {}", settings.volume);
}).detach();

